// Some portions generated by Claude
import assert from "node:assert/strict";
import test from "node:test";
import { expandQuery } from "../../../main/frontend/graph-explorer/rdf-vocabulary.ts";

/** The Workbench's Graph page accepts queries up to this many characters (graph-max-query-length). */
const SERVLET_LIMIT = 150000;

test("expanding many expanded nodes stays within the query length the Graph page accepts", () => {
  const ids = Array.from({ length: 40 }, (_, index) => `http://example.org/a-rather-long-namespace/resource-${index}`);
  const loaded = new Map(
    ids.map((id) => [
      id,
      {
        outgoing: Array.from({ length: 1000 }, (_, index) => ["<http://example.org/vocabulary/linksTo>", `<${id}/target-${index}>`]),
        incoming: Array.from({ length: 1000 }, (_, index) => [`<${id}/source-${index}>`, "<http://example.org/vocabulary/linksTo>"]),
      },
    ]),
  );
  const query = expandQuery(ids, 12, "default", true, loaded);
  assert.ok(query.length < SERVLET_LIMIT, `${query.length} characters`);
  assert.match(query, /MINUS \{ VALUES/, "loaded statements are still left out");
});

test("very long values are not written into the query; a node's other loaded statements still are", () => {
  const long = `"${"x".repeat(5000)}"`;
  const query = expandQuery(["urn:a"], 80, "default", false, new Map([["urn:a", { outgoing: [["<urn:p>", long], ["<urn:p>", "<urn:b>"]], incoming: [] }]]));
  assert.ok(!query.includes("xxxxxxxxxx"));
  assert.match(query, /\(<urn:p> <urn:b>\)/);
});
